@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : int
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemDescription : string
}

class PickupRequest {
  + RequestedDate : date
  + PickupTime : time
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteID : int
}

class Article {
  + Description : string
  + Category : string
  + RFIDTag : string
}

class FoodItem {
  + Description : string
}

class DistributionCenter {
  + Address : string
}

class Employee {
  + EmployeeID : int
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class Delivery {
  + DeliveryDate : date
}

City "1" -- "*" H2SLocation
H2SLocation "1" -- "*" DistributionCenter
H2SLocation "1" -- "*" PickupRequest
Resident "1" -- "*" PickupRequest
PickupRequest "1" -- "1" Article
PickupRequest "1" -- "1" FoodItem
Vehicle "*" -- "1" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
Vehicle "*" -- "1" DistributionCenter
DistributionCenter "1" -- "*" Article
DistributionCenter "1" -- "*" FoodItem
Employee "1" -- "*" Article : examines
Employee "1" -- "*" Client : calls
Employee "1" -- "*" Delivery : arranges
Client "1" -- "*" Delivery
Delivery "1" -- "1" Article
VolunteerDriver "1" -- "*" Delivery : performs

@enduml

